INSERT INTO `servicio_salidas` VALUES (62510,589,35,533,'Baixa Temporada DESDE 16/10/2025 ATE 15/11/2025','2025-10-16','10:00','09:15',4,6,7,9,20,20,0,283,'Pedimos la gentileza de presentarse en la oficina de Lagomar, en Rua Amaro Coelho 67, Barra da Lagoa, antes de las 9:15 h para realizar el check-in.\r\nPor respeto a quienes llegan a tiempo, no retrasamos la salida del barco incluso si alguien est├í en camino.\r\nTenga en cuenta el tr├ífico de Florian├│polis.\r\n\r\n┬À No disponemos de estacionamiento propio. Despu├®s de nuestra oficina, en la primera calle a la izquierda, hay varios estacionamientos por 30 reales.\r\n┬À Los visitantes con cualquier s├¡ntoma de gripe o resfriado no deben realizar los paseos durante el per├¡odo de pandemia.\r\n┬À Los clientes deben usar mascarilla mientras est├®n dentro del barco.\r\n┬À En caso de cancelaci├│n por mal tiempo, avisaremos lo antes posible (alrededor de las 8:00 h), ya que dependemos de varios factores para confirmar el paseo.\r\n┬À Pueden llevar sillas, sombrillas y conservadoras (cooler).\r\n┬À El restaurante de la isla no acepta tarjetas (ni d├®bito ni cr├®dito). En Barra da Lagoa no hay cajero autom├ítico.\r\n┬À No se reembolsar├í el valor pagado en caso de lluvia durante el paseo.\r\n┬À No nos responsabilizamos por las actividades contratadas en la isla. Si desea realizar alguna, contr├ítela al llegar, ya que las plazas son limitadas.\r\n\r\n???? +55 48 98494-7565 ÔÇö Lagomar',1,'BARRA DA LAGOA',NULL,'We kindly ask that you arrive at LagomarÔÇÖs office, located at Rua Amaro Coelho 67, Barra da Lagoa, by 9:15 a.m. for check-in.\r\nOut of respect for those who arrive on time, the boat will not wait or delay its departure, even if you are on your way.\r\nPlease consider the traffic in Florian├│polis.\r\n\r\n┬À We do not have private parking. After our office, take the first street on the left, where youÔÇÖll find several parking lots for 30 reais.\r\n┬À Visitors showing any flu or cold symptoms should not join the tours during the pandemic period.\r\n┬À Masks are required while inside the boat.\r\n┬À If the tour is canceled due to bad weather, we will inform you as soon as possible (around 8:00 a.m.). Several factors affect the confirmation of the trip.\r\n┬À You may bring chairs, umbrellas, and coolers.\r\n┬À The island restaurant does not accept cards (neither debit nor credit). There is no ATM in Barra da Lagoa.\r\n┬À No refunds will be issued in case of rain during the tour.\r\n┬À We are not responsible for activities purchased on the island. If you wish to join any, please book directly upon arrival, as spots are limited.\r\n\r\n???? +55 48 98494-7565 ÔÇö Lagomar','Pedimos a gentileza de comparecer ao escrit├│rio da Lagomar, localizado na Rua Amaro Coelho, 67 ÔÇô Barra da Lagoa, at├® as 9h15 para o check-in.\r\nPor respeito aos clientes que chegam no hor├írio, n├úo atrasamos a sa├¡da da escuna, mesmo que algu├®m ainda esteja a caminho.\r\n├ë importante levar em considera├º├úo o tr├ónsito de Florian├│polis.\r\n\r\n┬À N├úo possu├¡mos estacionamento pr├│prio. Ap├│s o nosso escrit├│rio, a primeira rua ├á esquerda conta com v├írios estacionamentos por cerca de R$ 30.\r\n┬À Visitantes com sintomas de gripe ou resfriado n├úo devem realizar o passeio durante o per├¡odo da pandemia.\r\n┬À Os clientes devem usar m├íscara enquanto estiverem dentro da escuna.\r\n┬À Em caso de cancelamento por mau tempo, avisaremos o mais cedo poss├¡vel (por volta das 8h), pois dependemos de diversos fatores para confirmar o passeio.\r\n┬À ├ë permitido levar cadeiras, guarda-s├│is e cooler (conservadora).\r\n┬À O restaurante da ilha n├úo aceita cart├Áes (nem d├®bito, nem cr├®dito). Na Barra da Lagoa n├úo h├í caixa eletr├┤nico.\r\n┬À N├úo ser├í devolvido o valor pago caso ocorra chuva durante o passeio.\r\n┬À N├úo nos responsabilizamos por atividades contratadas na ilha. Se desejar participar de alguma, contrate apenas ao chegar, pois as vagas s├úo limitadas.\r\n\r\n???? +55 48 98494-7565 ÔÇö Lagomar','Chiediamo gentilmente di presentarsi allÔÇÖufficio Lagomar, in Rua Amaro Coelho 67, Barra da Lagoa, entro le 9:15 per il check-in.\r\nPer rispetto di chi arriva puntuale, la partenza della barca non verr├á ritardata, anche se qualcuno ├¿ ancora in viaggio.\r\nSi prega di tenere conto del traffico di Florian├│polis.\r\n\r\n┬À Non abbiamo parcheggio privato. Dopo il nostro ufficio, alla prima strada a sinistra, ci sono diversi parcheggi a 30 real.\r\n┬À I visitatori con sintomi di influenza o raffreddore non devono partecipare alle escursioni durante il periodo della pandemia.\r\n┬À I clienti devono indossare la mascherina mentre si trovano sulla barca.\r\n┬À In caso di cancellazione per maltempo, avviseremo il prima possibile (intorno alle 8:00), poich├® la conferma del tour dipende da diversi fattori.\r\n┬À ├ê possibile portare sedie, ombrelloni e borse frigo (cooler).\r\n┬À Il ristorante dellÔÇÖisola non accetta carte (n├® di debito n├® di credito). A Barra da Lagoa non cÔÇÖ├¿ bancomat.\r\n┬À Non verr├á rimborsato lÔÇÖimporto pagato in caso di pioggia durante il tour.\r\n┬À Non siamo responsabili per le attivit├á acquistate sullÔÇÖisola. Se desiderate partecipare a qualcuna, contrattatela direttamente allÔÇÖarrivo, poich├® i posti sono limitati.\r\n\r\n???? +55 48 98494-7565 ÔÇö Lagomar',NULL,NULL,NULL),(62511,589,35,533,'Baixa Temporada DESDE 16/10/2025 ATE 15/11/2025','2025-10-17','10:00','09:15',4,6,7,9,20,19,1,283,'Pedimos la gentileza de presentarse en la oficina de Lagomar, en Rua Amaro Coelho 67, Barra da Lagoa, antes de las 9:15 h para realizar el check-in.\r\nPor respeto a quienes llegan a tiempo, no retrasamos la salida del barco incluso si alguien est├í en camino.\r\nTenga en cuenta el tr├ífico de Florian├│polis.\r\n\r\n┬À No disponemos de estacionamiento propio. Despu├®s de nuestra oficina, en la primera calle a la izquierda, hay varios estacionamientos por 30 reales.\r\n┬À Los visitantes con cualquier s├¡ntoma de gripe o resfriado no deben realizar l